    }

    @Throws(IOException::class)
    override fun end() {
        logger.trace("TOKENIZER-END {}", finalOffset)
        super.end()
        offsetAtt.setOffset(finalOffset, finalOffset)
    }

    @Throws(IOException::class)
    override fun reset() {
        logger.trace("TOKENIZER-RESET")
        super.reset()
        position = 0
        extLength = 0
        baseOffset = 0
        readLength = 0
        finalOffset = 0
        tokenLength = 0
        chrCurrent = 0.toChar()
        typeCurrent = null
        tabularFull = false
    }

    @Throws(IOException::class)
    override fun close() {
        logger.trace("TOKENIZER-CLOSE")
