class ProductNameAnalysisAction : BaseRestHandler() {

    private var indexingThread: DanawaBulkTextIndexer? = null
    private var migratingThread: FastcatMigrateIndexer? = null

    override fun routes(): List<Route> {
        return Collections.unmodifiableList(Arrays.asList(
            Route(GET, "$BASE_URI/{action}"),
            Route(POST, "$BASE_URI/{action}"),
            Route(GET, "$BASE_URI/"),
            Route(POST, "$BASE_URI/")))
    }

    override fun getName(): String {
        return "rest_handler_product_name_analysis"
    }

    @Throws(IOException::class)
    override fun prepareRequest(request: RestRequest, client: NodeClient): RestChannelConsumer {
        val action = request.param("action")
        val buffer = StringWriter()
        val builder = JSONWriter(buffer)

        if (ACTION_TEST == action) {
            testAction(request, client, builder)
            builder.`object`().key("action").value(action).endObject()
        } else if (ACTION_RELOAD_DICT == action) {
            reloadDictionary()
            builder.`object`().key("action").value(action).endObject()
        } else if (ACTION_INFO_DICT == action) {
            builder.`object`().key("action").value(action)
            infoDictionary(request, client, builder)
            builder.endObject()
        } else if (ACTION_FIND_DICT == action) {
            builder.`object`().key("action").value(action)
            findDictionary(request, client, builder)
            builder.endObject()
        } else if (ACTION_RESTORE_DICT == action) {
            restoreDictionary(request, client)
            builder.`object`().key("action").value(action).endObject()
        } else if (ACTION_COMPILE_DICT == action) {
            compileDictionary(request, client)
            builder.`object`().key("action").value(action).endObject()
        } else if (ACTION_FULL_INDEX == action) {
            val count = bulkIndex(request, client)
            builder.`object`().key("action").value(action)
            if (count > 0) {
                builder.key("working").value("true").key("count").value(count)
            } else {
                builder.key("working").value("false")
            }
            builder.endObject()
        } else if (ACTION_FASTCAT_INDEX == action) {
            val count = fastcatIndex(request, client)
            builder.`object`().key("action").value(action)
            if (count > 0) {
                builder.key("working").value("true").key("count").value(count)
            } else {
                builder.key("working").value("false")
            }
            builder.endObject()
        } else if (ACTION_ANALYZE_TEXT == action) {
            analyzeTextAction(request, client, builder)
        } else if (ACTION_SEARCH == action) {
            search(request, client, builder)
        } else if (ACTION_BUILD_QUERY == action) {
            buildQuery(request, client, builder)
        } else if (ACTION_ANALYZE_MULTI_PARAMS == action) {
            builder.`object`()
            analyzeMultiParamsAction(request, client, builder)
            builder.endObject()
        } else if (ACTION_SYNONYM_LIST == action) {
            builder.`object`()
            getSynonymListAction(request, client, builder)
            builder.endObject()
        } else if (ACTION_SEARCH_KEYWORD == action) {
            makeSearchKeyword(request, client, builder)
        } else if (ACTION_CHECK_ENABLE == action) {
            builder.`object`().key("loaded").value(getDictionary() != null)
            builder.endObject()
        }
        return RestChannelConsumer { channel ->
            channel.sendResponse(RestResponse(RestStatus.OK, CONTENT_TYPE_JSON, BytesArray(buffer.toString().toByteArray(StandardCharsets.UTF_8))))
        }
    }

    private fun parseRequestBody(request: RestRequest): JSONObject {
        var ret = JSONObject()
        try {
            ret = JSONObject(JSONTokener(request.content().utf8ToString()))
        } catch (ignore: Exception) { }
        return ret
    }

    fun testAction(request: RestRequest, client: NodeClient, writer: JSONWriter) {
        logger.debug("TEST-ACTION")
    }

    private fun distribute(client: NodeClient, action: String, body: JSONObject, selfDist: Boolean) {
        val localNodeId = client.localNodeId
        val infoRequest = NodesInfoRequest()
        infoRequest.clear()
            .addMetrics(NodesInfoMetrics.Metric.JVM.metricName())
            .addMetrics(NodesInfoMetrics.Metric.OS.metricName())
            .addMetrics(NodesInfoMetrics.Metric.PROCESS.metricName())
            .addMetrics(NodesInfoMetrics.Metric.HTTP.metricName())
            .addMetrics(NodesInfoMetrics.Metric.PLUGINS.metricName())
            .addMetrics(NodesInfoMetrics.Metric.INDICES.metricName())

        try {
            val response = client.admin().cluster().nodesInfo(infoRequest).get()
            val nodes = response.nodes
            for (node in nodes) {
                if (!selfDist && localNodeId == node.node.id) {
                    continue
                }
                var hasPlugin = false
                val address = node.getInfo(HttpInfo::class.java).address().publishAddress()
                val plugins = node.getInfo(PluginsAndModules::class.java).pluginInfos
                for (info in plugins) {
                    hasPlugin = info.descriptor().classname == AnalysisProductNamePlugin::class.java.name
                    if (hasPlugin) break
                }
                if (hasPlugin) {
                    logger.debug("NODE: {}:{}", address.address, address.port)
                    doRestRequest(address.address, address.port, action, body)
                }
            }
        } catch (e: Exception) {
            logger.error("", e)
        }
    }

    private fun doRestRequest(address: String, port: Int, action: String, body: JSONObject): String {
        val sb = StringBuilder()
        var con: HttpURLConnection? = null
        var ostream: OutputStream? = null
        var reader: BufferedReader? = null
        try {
            val url = "http://$address:$port$BASE_URI/$action"
            logger.debug("SEND REQUEST {}", url)
            con = URL(url).openConnection() as HttpURLConnection
            con.requestMethod = "POST"
            con.setRequestProperty("Content-Type", "application/json")
            con.doOutput = true
            ostream = con.outputStream
            ostream.write(body.toString().toByteArray())
            ostream.flush()
            val responseCode = con.responseCode
            if (responseCode == HttpURLConnection.HTTP_CREATED) {
                logger.trace("RESPONSE:{}", responseCode)
                reader = BufferedReader(InputStreamReader(con.inputStream))
                var rl: String?
                while (reader.readLine().also { rl = it } != null) {
                    sb.append(rl).append("\r\n")
                }
                logger.trace("RESPONSE:{}", sb)
            }
        } catch (e: Exception) {
            logger.error("", e)
        } finally {
            try { ostream?.close() } catch (ignore: Exception) { }
            try { reader?.close() } catch (ignore: Exception) { }
        }
        return sb.toString()
    }

